use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    let mut last_key = None;

    for line in input.as_array() {
        let mut row = line.as_array();
        let mut value = row.pop().unwrap_or(0);

        if let Some(last_key) = last_key {
            if last_key == value {
                continue;
            }
        }

        result.push(vec![last_key, value]);
        last_key = Some(value);
    }

    result.sort_by(|a, b| a[0].cmp(&b[0]));

    serde_json::Value::from(result)
}
